{
  "name": "通用USB设备通信后端接口",
  "name_en": "Generic USB Device Communication Backend Interface",
  "manufacturer": "",
  "description": "这是一个面向通用USB设备的通信后端接口，用于在系统中枚举USB设备、读取各类USB描述符、打开与关闭设备连接，并执行控制传输、批量传输、中断传输和等时传输。它常用于实验室软件与各种通过USB连接的仪器、控制器或数据采集设备之间建立底层通信。",
  "description_en": "This is a generic communication backend interface for USB devices. It is used to enumerate USB devices on a system, read USB descriptors, open and close device connections, and perform control, bulk, interrupt, and isochronous transfers. It is commonly used as a low-level communication layer between laboratory software and USB-connected instruments, controllers, or data acquisition devices.",
  "tag_hints": [
    "USB communication",
    "device enumeration",
    "USB descriptors",
    "control transfer",
    "bulk transfer",
    "interrupt transfer",
    "isochronous transfer",
    "interface claiming"
  ],
  "actions": [
    {
      "action_name": "auto-enumerate_devices",
      "description": "枚举系统中的USB设备。",
      "description_en": "Enumerate USB devices present in the system."
    },
    {
      "action_name": "auto-get_parent",
      "description": "获取指定USB设备的父设备。",
      "description_en": "Get the parent device of a specified USB device."
    },
    {
      "action_name": "auto-get_device_descriptor",
      "description": "获取设备描述符。",
      "description_en": "Get the device descriptor."
    },
    {
      "action_name": "auto-get_configuration_descriptor",
      "description": "获取配置描述符。",
      "description_en": "Get a configuration descriptor."
    },
    {
      "action_name": "auto-get_interface_descriptor",
      "description": "获取接口描述符。",
      "description_en": "Get an interface descriptor."
    },
    {
      "action_name": "auto-get_endpoint_descriptor",
      "description": "获取端点描述符。",
      "description_en": "Get an endpoint descriptor."
    },
    {
      "action_name": "auto-open_device",
      "description": "打开USB设备以进行数据通信。",
      "description_en": "Open a USB device for data communication."
    },
    {
      "action_name": "auto-close_device",
      "description": "关闭USB设备连接。",
      "description_en": "Close the USB device connection."
    },
    {
      "action_name": "auto-set_configuration",
      "description": "设置设备的活动USB配置。",
      "description_en": "Set the active USB configuration of the device."
    },
    {
      "action_name": "auto-get_configuration",
      "description": "获取设备当前的活动USB配置。",
      "description_en": "Get the device's current active USB configuration."
    },
    {
      "action_name": "auto-set_interface_altsetting",
      "description": "设置接口的备用设置。",
      "description_en": "Set the alternate setting of an interface."
    },
    {
      "action_name": "auto-claim_interface",
      "description": "声明并独占访问指定接口。",
      "description_en": "Claim exclusive access to a specified interface."
    },
    {
      "action_name": "auto-release_interface",
      "description": "释放已声明的接口。",
      "description_en": "Release a previously claimed interface."
    },
    {
      "action_name": "auto-bulk_write",
      "description": "通过批量端点写入数据。",
      "description_en": "Write data through a bulk endpoint."
    },
    {
      "action_name": "auto-bulk_read",
      "description": "通过批量端点读取数据。",
      "description_en": "Read data through a bulk endpoint."
    },
    {
      "action_name": "auto-intr_write",
      "description": "通过中断端点写入数据。",
      "description_en": "Write data through an interrupt endpoint."
    },
    {
      "action_name": "auto-intr_read",
      "description": "通过中断端点读取数据。",
      "description_en": "Read data through an interrupt endpoint."
    },
    {
      "action_name": "auto-iso_write",
      "description": "通过等时端点写入数据。",
      "description_en": "Write data through an isochronous endpoint."
    },
    {
      "action_name": "auto-iso_read",
      "description": "通过等时端点读取数据。",
      "description_en": "Read data through an isochronous endpoint."
    },
    {
      "action_name": "auto-ctrl_transfer",
      "description": "在端点0上执行USB控制传输。",
      "description_en": "Perform a USB control transfer on endpoint 0."
    },
    {
      "action_name": "auto-clear_halt",
      "description": "清除端点的暂停或STALL状态。",
      "description_en": "Clear the halt or stall condition on an endpoint."
    },
    {
      "action_name": "auto-reset_device",
      "description": "复位USB设备。",
      "description_en": "Reset the USB device."
    },
    {
      "action_name": "auto-is_kernel_driver_active",
      "description": "检查接口上是否有内核驱动处于活动状态。",
      "description_en": "Check whether a kernel driver is active on an interface."
    },
    {
      "action_name": "auto-detach_kernel_driver",
      "description": "从接口分离内核驱动。",
      "description_en": "Detach the kernel driver from an interface."
    },
    {
      "action_name": "auto-attach_kernel_driver",
      "description": "将内核驱动重新附加到接口。",
      "description_en": "Re-attach the kernel driver to an interface."
    }
  ]
}

